// Manual argument parsing for hexyl

#[derive(Debug, Clone, PartialEq)]
pub enum ColorWhen { Always, Auto, Never, Force }

#[derive(Debug, Clone, PartialEq)]
pub enum BorderStyle { Unicode, Ascii, None }

#[derive(Debug, Clone, PartialEq)]
pub enum CharacterTable { Default, Ascii, Codepage1047, Codepage437, Braille }

#[derive(Debug, Clone, PartialEq)]
pub enum ColorScheme { Default, Gradient }

#[derive(Debug, Clone, PartialEq)]
pub enum Base { Binary, Octal, Decimal, Hexadecimal }

#[derive(Debug, Clone, PartialEq)]
pub enum Endianness { Big, Little }

#[derive(Debug, Clone, PartialEq)]
pub enum GroupSize { One = 1, Two = 2, Four = 4, Eight = 8 }

#[derive(Debug, Clone)]
pub enum PanelsArg { Auto, Count(usize) }

#[derive(Debug)]
pub struct Args {
    pub file: Option<String>,
    pub length: Option<u64>,
    pub skip: Option<i64>,
    pub block_size: u64,
    pub no_squeezing: bool,
    pub color: ColorWhen,
    pub border: BorderStyle,
    pub plain: bool,
    pub no_characters: bool,
    pub characters: bool,
    pub character_table: CharacterTable,
    pub color_scheme: ColorScheme,
    pub no_position: bool,
    pub display_offset: i64,
    pub panels: Option<PanelsArg>,
    pub group_size: GroupSize,
    pub endianness: Endianness,
    pub base: Base,
    pub terminal_width: Option<u32>,
    pub print_color_table: bool,
    pub include: bool,
    pub completion: Option<String>,
    pub version: bool,
    pub help: bool,
    pub help_short: bool,
}

impl Default for Args {
    fn default() -> Self {
        Args {
            file: None, length: None, skip: None,
            block_size: 512, no_squeezing: false,
            color: ColorWhen::Always, border: BorderStyle::Unicode,
            plain: false, no_characters: false, characters: false,
            character_table: CharacterTable::Default, color_scheme: ColorScheme::Default,
            no_position: false, display_offset: 0, panels: None,
            group_size: GroupSize::One, endianness: Endianness::Big,
            base: Base::Hexadecimal, terminal_width: None,
            print_color_table: false, include: false, completion: None,
            version: false, help: false, help_short: false,
        }
    }
}

/// Parse a byte count string with optional unit
pub fn parse_byte_count(s: &str, block_size: u64, negative_ok: bool) -> Result<i64, String> {
    if s.is_empty() {
        return Err("empty string".to_string());
    }

    let negative = s.starts_with('-');
    let s = if negative { &s[1..] } else { s };

    if !negative_ok && negative {
        return Err("negative offset specified, but only positive offsets (counts) are accepted in this context".to_string());
    }

    // Check for hex
    let (num_str, unit) = if s.starts_with("0x") || s.starts_with("0X") {
        (&s[2..], "")
    } else {
        // Find where the number ends and unit begins
        let split_pos = s.find(|c: char| c.is_alphabetic()).unwrap_or(s.len());
        (&s[..split_pos], &s[split_pos..])
    };

    // Check for hex prefix
    let value: u64 = if num_str.is_empty() {
        return Err(format!("invalid number"));
    } else if s.starts_with("0x") || s.starts_with("0X") {
        u64::from_str_radix(num_str, 16).map_err(|_| format!("invalid hex number '{}'", num_str))?
    } else {
        num_str.parse::<u64>().map_err(|_| format!("invalid number '{}'", num_str))?
    };

    let multiplier: u64 = match unit {
        "" => 1,
        "kB" => 1000,
        "MB" => 1_000_000,
        "GB" => 1_000_000_000,
        "TB" => 1_000_000_000_000,
        "kiB" | "KiB" => 1024,
        "MiB" => 1024 * 1024,
        "GiB" => 1024 * 1024 * 1024,
        "TiB" => 1024_u64 * 1024 * 1024 * 1024,
        "block" => block_size,
        other => return Err(format!("invalid unit \"{}\"", other)),
    };

    let result = value.checked_mul(multiplier)
        .ok_or_else(|| format!("overflow"))?;

    if negative {
        Ok(-(result as i64))
    } else {
        Ok(result as i64)
    }
}

pub fn parse_args(args: &[String], prog_name: &str) -> Result<Args, String> {
    let mut result = Args::default();
    let mut i = 0;
    let mut file_set = false;
    let mut endian_set = false;

    // Check for -h as first pass
    for arg in args {
        if arg == "-h" {
            result.help_short = true;
            return Ok(result);
        }
        if arg == "--help" {
            result.help = true;
            return Ok(result);
        }
        if arg == "-V" || arg == "--version" {
            result.version = true;
            return Ok(result);
        }
    }

    while i < args.len() {
        let arg = &args[i];

        if arg == "--" {
            i += 1;
            // rest are positional
            while i < args.len() {
                if file_set {
                    return Err(format!("error: unexpected argument '{}' found\n\nUsage: {} [OPTIONS] [FILE]\n\nFor more information, try '--help'.", args[i], prog_name));
                }
                result.file = Some(args[i].clone());
                file_set = true;
                i += 1;
            }
            break;
        }

        // Long options with = sign
        if arg.starts_with("--") {
            let (key, val_opt) = if let Some(eq) = arg.find('=') {
                (&arg[..eq], Some(&arg[eq+1..]))
            } else {
                (arg.as_str(), None::<&str>)
            };

            macro_rules! get_val {
                ($opt:expr) => {
                    if let Some(v) = val_opt {
                        v.to_string()
                    } else if i + 1 < args.len() {
                        i += 1;
                        args[i].clone()
                    } else {
                        return Err(format!("error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.", $opt));
                    }
                }
            }

            match key {
                "--length" | "--bytes" => {
                    let v = get_val!("--length <N>");
                    let n = parse_byte_count(&v, result.block_size, false)
                        .map_err(|e| format!("Error: failed to parse `--length` arg \"{}\" as byte count\n\nCaused by:\n    {}", v, e))?;
                    result.length = Some(n as u64);
                }
                "--skip" => {
                    let v = get_val!("--skip <N>");
                    let n = parse_byte_count(&v, result.block_size, true)
                        .map_err(|e| format!("Error: failed to parse `--skip` arg \"{}\" as byte count\n\nCaused by:\n    {}", v, e))?;
                    result.skip = Some(n);
                }
                "--block-size" => {
                    let v = get_val!("--block-size <SIZE>");
                    let n = parse_byte_count(&v, 512, false)
                        .map_err(|e| format!("Error: failed to parse `--block-size` arg \"{}\" as byte count\n\nCaused by:\n    {}", v, e))?;
                    result.block_size = n as u64;
                }
                "--no-squeezing" => { result.no_squeezing = true; }
                "--color" => {
                    let v = get_val!("--color <WHEN>");
                    result.color = match v.as_str() {
                        "always" => ColorWhen::Always,
                        "auto" => ColorWhen::Auto,
                        "never" => ColorWhen::Never,
                        "force" => ColorWhen::Force,
                        _ => return Err(format!("error: invalid value '{}' for '--color <WHEN>'\n  [possible values: always, auto, never, force]\n\nFor more information, try '--help'.", v)),
                    };
                }
                "--border" => {
                    let v = get_val!("--border <STYLE>");
                    result.border = match v.as_str() {
                        "unicode" => BorderStyle::Unicode,
                        "ascii" => BorderStyle::Ascii,
                        "none" => BorderStyle::None,
                        _ => return Err(format!("error: invalid value '{}' for '--border <STYLE>'\n  [possible values: unicode, ascii, none]\n\nFor more information, try '--help'.", v)),
                    };
                }
                "--plain" => { result.plain = true; }
                "--no-characters" => { result.no_characters = true; }
                "--characters" => { result.characters = true; }
                "--character-table" => {
                    let v = get_val!("--character-table <FORMAT>");
                    result.character_table = match v.as_str() {
                        "default" => CharacterTable::Default,
                        "ascii" => CharacterTable::Ascii,
                        "codepage-1047" => CharacterTable::Codepage1047,
                        "codepage-437" => CharacterTable::Codepage437,
                        "braille" => CharacterTable::Braille,
                        _ => return Err(format!("error: invalid value '{}' for '--character-table <FORMAT>'\n\nFor more information, try '--help'.", v)),
                    };
                }
                "--color-scheme" => {
                    let v = get_val!("--color-scheme <FORMAT>");
                    result.color_scheme = match v.as_str() {
                        "default" => ColorScheme::Default,
                        "gradient" => ColorScheme::Gradient,
                        _ => return Err(format!("error: invalid value '{}' for '--color-scheme <FORMAT>'\n\nFor more information, try '--help'.", v)),
                    };
                }
                "--no-position" => { result.no_position = true; }
                "--display-offset" => {
                    let v = get_val!("--display-offset <N>");
                    let n = parse_byte_count(&v, result.block_size, true)
                        .map_err(|e| format!("Error: failed to parse `--display-offset` arg \"{}\" as byte count\n\nCaused by:\n    {}", v, e))?;
                    result.display_offset = n;
                }
                "--panels" => {
                    let v = get_val!("--panels <N>");
                    if v == "auto" {
                        result.panels = Some(PanelsArg::Auto);
                    } else {
                        let n: usize = v.parse().map_err(|_| format!("error: invalid value '{}' for '--panels <N>'\n\nFor more information, try '--help'.", v))?;
                        result.panels = Some(PanelsArg::Count(n));
                    }
                }
                "--group-size" | "--groupsize" => {
                    let v = get_val!("--group-size <N>");
                    result.group_size = match v.as_str() {
                        "1" => GroupSize::One,
                        "2" => GroupSize::Two,
                        "4" => GroupSize::Four,
                        "8" => GroupSize::Eight,
                        _ => return Err(format!("error: invalid value '{}' for '--group-size <N>'\n  [possible values: 1, 2, 4, 8]\n\nFor more information, try '--help'.", v)),
                    };
                }
                "--endianness" => {
                    let v = get_val!("--endianness <FORMAT>");
                    result.endianness = match v.as_str() {
                        "little" => Endianness::Little,
                        "big" => Endianness::Big,
                        _ => return Err(format!("error: invalid value '{}' for '--endianness <FORMAT>'\n\nFor more information, try '--help'.", v)),
                    };
                    endian_set = true;
                }
                "--base" => {
                    let v = get_val!("--base <B>");
                    result.base = match v.as_str() {
                        "binary" => Base::Binary,
                        "octal" => Base::Octal,
                        "decimal" => Base::Decimal,
                        "hexadecimal" => Base::Hexadecimal,
                        _ => return Err(format!("error: invalid value '{}' for '--base <B>'\n\nFor more information, try '--help'.", v)),
                    };
                }
                "--terminal-width" => {
                    let v = get_val!("--terminal-width <N>");
                    let n: u32 = v.parse().map_err(|_| format!("error: invalid value '{}' for '--terminal-width'\n\nFor more information, try '--help'.", v))?;
                    result.terminal_width = Some(n);
                }
                "--print-color-table" => { result.print_color_table = true; }
                "--include" => { result.include = true; }
                "--completion" => {
                    let v = get_val!("--completion <SHELL>");
                    match v.as_str() {
                        "bash" | "elvish" | "fish" | "powershell" | "zsh" => {
                            result.completion = Some(v);
                        }
                        _ => return Err(format!("error: invalid value '{}' for '--completion <SHELL>'\n  [possible values: bash, elvish, fish, powershell, zsh]\n\nFor more information, try '--help'.", v)),
                    }
                }
                "--help" => { result.help = true; return Ok(result); }
                "--version" => { result.version = true; return Ok(result); }
                other => {
                    return Err(format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: {} [OPTIONS] [FILE]\n\nFor more information, try '--help'.", other, other, other, prog_name));
                }
            }
        } else if arg.starts_with('-') && arg.len() > 1 {
            // Short options
            let flags = &arg[1..];
            let mut j = 0;
            let flag_chars: Vec<char> = flags.chars().collect();
            while j < flag_chars.len() {
                let ch = flag_chars[j];
                match ch {
                    'n' | 'c' | 'l' => {
                        // require value
                        let v = if j + 1 < flag_chars.len() {
                            let s: String = flag_chars[j+1..].iter().collect();
                            j = flag_chars.len();
                            s
                        } else if i + 1 < args.len() {
                            i += 1;
                            args[i].clone()
                        } else {
                            let long = if ch == 'n' { "--length" } else if ch == 'c' { "--length" } else { "--length" };
                            return Err(format!("error: a value is required for '-{} <N>' but none was supplied\n\nFor more information, try '--help'.", ch));
                        };
                        let n = parse_byte_count(&v, result.block_size, false)
                            .map_err(|e| format!("Error: failed to parse `--length` arg \"{}\" as byte count\n\nCaused by:\n    {}", v, e))?;
                        result.length = Some(n as u64);
                    }
                    's' => {
                        let v = if j + 1 < flag_chars.len() {
                            let s: String = flag_chars[j+1..].iter().collect();
                            j = flag_chars.len();
                            s
                        } else if i + 1 < args.len() {
                            i += 1;
                            args[i].clone()
                        } else {
                            return Err(format!("error: a value is required for '-s <N>' but none was supplied\n\nFor more information, try '--help'."));
                        };
                        let n = parse_byte_count(&v, result.block_size, true)
                            .map_err(|e| format!("Error: failed to parse `--skip` arg \"{}\" as byte count\n\nCaused by:\n    {}", v, e))?;
                        result.skip = Some(n);
                    }
                    'v' => { result.no_squeezing = true; }
                    'p' => { result.plain = true; }
                    'C' => { result.characters = true; }
                    'P' => { result.no_position = true; }
                    'o' => {
                        let v = if j + 1 < flag_chars.len() {
                            let s: String = flag_chars[j+1..].iter().collect();
                            j = flag_chars.len();
                            s
                        } else if i + 1 < args.len() {
                            i += 1;
                            args[i].clone()
                        } else {
                            return Err(format!("error: a value is required for '-o <N>' but none was supplied\n\nFor more information, try '--help'."));
                        };
                        let n = parse_byte_count(&v, result.block_size, true)
                            .map_err(|e| format!("Error: failed to parse `--display-offset` arg \"{}\" as byte count\n\nCaused by:\n    {}", v, e))?;
                        result.display_offset = n;
                    }
                    'g' => {
                        let v = if j + 1 < flag_chars.len() {
                            let s: String = flag_chars[j+1..].iter().collect();
                            j = flag_chars.len();
                            s
                        } else if i + 1 < args.len() {
                            i += 1;
                            args[i].clone()
                        } else {
                            return Err(format!("error: a value is required for '-g <N>' but none was supplied\n\nFor more information, try '--help'."));
                        };
                        result.group_size = match v.as_str() {
                            "1" => GroupSize::One,
                            "2" => GroupSize::Two,
                            "4" => GroupSize::Four,
                            "8" => GroupSize::Eight,
                            _ => return Err(format!("error: invalid value '{}' for '--group-size <N>'\n  [possible values: 1, 2, 4, 8]\n\nFor more information, try '--help'.", v)),
                        };
                    }
                    'e' => {
                        result.endianness = Endianness::Little;
                        endian_set = true;
                    }
                    'b' => {
                        let v = if j + 1 < flag_chars.len() {
                            let s: String = flag_chars[j+1..].iter().collect();
                            j = flag_chars.len();
                            s
                        } else if i + 1 < args.len() {
                            i += 1;
                            args[i].clone()
                        } else {
                            return Err(format!("error: a value is required for '-b <B>' but none was supplied\n\nFor more information, try '--help'."));
                        };
                        result.base = match v.as_str() {
                            "binary" => Base::Binary,
                            "octal" => Base::Octal,
                            "decimal" => Base::Decimal,
                            "hexadecimal" => Base::Hexadecimal,
                            _ => return Err(format!("error: invalid value '{}' for '--base <B>'\n\nFor more information, try '--help'.", v)),
                        };
                    }
                    'i' => { result.include = true; }
                    'h' => { result.help_short = true; return Ok(result); }
                    'V' => { result.version = true; return Ok(result); }
                    other => {
                        return Err(format!("error: unexpected argument '-{}' found\n\nUsage: {} [OPTIONS] [FILE]\n\nFor more information, try '--help'.", other, prog_name));
                    }
                }
                j += 1;
            }
        } else {
            // Positional argument (file)
            if file_set {
                return Err(format!("error: unexpected argument '{}' found\n\nUsage: {} [OPTIONS] [FILE]\n\nFor more information, try '--help'.", arg, prog_name));
            }
            result.file = Some(arg.clone());
            file_set = true;
        }

        i += 1;
    }

    // Validate: --panels and --terminal-width are mutually exclusive
    if result.panels.is_some() && result.terminal_width.is_some() {
        return Err(format!("error: the argument '--panels <N>' cannot be used with '--terminal-width <N>'\n\nUsage: {} --panels <N> [FILE]\n\nFor more information, try '--help'.", prog_name));
    }

    Ok(result)
}

