                let ch = flag_chars[j];
                match ch {
                    'n' | 'c' | 'l' => {
                        // require value
                        let v = if j + 1 < flag_chars.len() {
                            let s: String = flag_chars[j+1..].iter().collect();
                            j = flag_chars.len();
                            s
                        } else if i + 1 < args.len() {
                            i += 1;
                            args[i].clone()
                        } else {
                            let long = if ch == 'n' { "--length" } else if ch == 'c' { "--length" } else { "--length" };
                            return Err(format!("error: a value is required for '-{} <N>' but none was supplied\n\nFor more information, try '--help'.", ch));
                        };
                        let n = parse_byte_count(&v, result.block_size, false)
                            .map_err(|e| format!("Error: failed to parse `--length` arg \"{}\" as byte count\n\nCaused by:\n    {}", v, e))?;
                        result.length = Some(n as u64);
                    }
                    's' => {
                        let v = if j + 1 < flag_chars.len() {
                            let s: String = flag_chars[j+1..].iter().collect();
                            j = flag_chars.len();
                            s
                        } else if i + 1 < args.len() {
                            i += 1;
                            args[i].clone()
                        } else {
                            return Err(format!("error: a value is required for '-s <N>' but none was supplied\n\nFor more information, try '--help'."));
                        };
                        let n = parse_byte_count(&v, result.block_size, true)
                            .map_err(|e| format!("Error: failed to parse `--skip` arg \"{}\" as byte count\n\nCaused by:\n    {}", v, e))?;
                        result.skip = Some(n);
                    }
                    'v' => { result.no_squeezing = true; }
                    'p' => { result.plain = true; }
                    'C' => { result.characters = true; }
                    'P' => { result.no_position = true; }
                    'o' => {
                        let v = if j + 1 < flag_chars.len() {
                            let s: String = flag_chars[j+1..].iter().collect();
                            j = flag_chars.len();
                            s
                        } else if i + 1 < args.len() {
                            i += 1;
                            args[i].clone()
                        } else {
                            return Err(format!("error: a value is required for '-o <N>' but none was supplied\n\nFor more information, try '--help'."));
                        };
                        let n = parse_byte_count(&v, result.block_size, true)
                            .map_err(|e| format!("Error: failed to parse `--display-offset` arg \"{}\" as byte count\n\nCaused by:\n    {}", v, e))?;
                        result.display_offset = n;
                    }
                    'g' => {
                        let v = if j + 1 < flag_chars.len() {
                            let s: String = flag_chars[j+1..].iter().collect();
                            j = flag_chars.len();
                            s
                        } else if i + 1 < args.len() {
                            i += 1;
                            args[i].clone()
                        } else {
                            return Err(format!("error: a value is required for '-g <N>' but none was supplied\n\nFor more information, try '--help'."));
                        };
                        result.group_size = match v.as_str() {
                            "1" => GroupSize::One,
                            "2" => GroupSize::Two,
                            "4" => GroupSize::Four,
                            "8" => GroupSize::Eight,
                            _ => return Err(format!("error: invalid value '{}' for '--group-size <N>'\n  [possible values: 1, 2, 4, 8]\n\nFor more information, try '--help'.", v)),
                        };
                    }
                    'e' => {
                        result.endianness = Endianness::Little;
                        endian_set = true;
                    }
                    'b' => {
                        let v = if j + 1 < flag_chars.len() {
                            let s: String = flag_chars[j+1..].iter().collect();
                            j = flag_chars.len();
                            s
                        } else if i + 1 < args.len() {
                            i += 1;
                            args[i].clone()
                        } else {
                            return Err(format!("error: a value is required for '-b <B>' but none was supplied\n\nFor more information, try '--help'."));
                        };
                        result.base = match v.as_str() {
                            "binary" => Base::Binary,
                            "octal" => Base::Octal,
                            "decimal" => Base::Decimal,
                            "hexadecimal" => Base::Hexadecimal,
                            _ => return Err(format!("error: invalid value '{}' for '--base <B>'\n\nFor more information, try '--help'.", v)),
                        };
                    }
                    'i' => { result.include = true; }
                    'h' => { result.help_short = true; return Ok(result); }
                    'V' => { result.version = true; return Ok(result); }
                    other => {
                        return Err(format!("error: unexpected argument '-{}' found\n\nUsage: {} [OPTIONS] [FILE]\n\nFor more information, try '--help'.", other, prog_name));
                    }
                }
                j += 1;
            }
        } else {
            // Positional argument (file)
            if file_set {
                return Err(format!("error: unexpected argument '{}' found\n\nUsage: {} [OPTIONS] [FILE]\n\nFor more information, try '--help'.", arg, prog_name));
            }
            result.file = Some(arg.clone());
            file_set = true;
        }

        i += 1;
    }

    // Validate: --panels and --terminal-width are mutually exclusive
    if result.panels.is_some() && result.terminal_width.is_some() {
        return Err(format!("error: the argument '--panels <N>' cannot be used with '--terminal-width <N>'\n\nUsage: {} --panels <N> [FILE]\n\nFor more information, try '--help'.", prog_name));
    }

    Ok(result)
}

