}

fn byte_to_char(b: u8, table: &CharacterTable) -> char {
    match table {
        CharacterTable::Default => byte_to_char_default(b),
        CharacterTable::Ascii => byte_to_char_ascii(b),
        CharacterTable::Codepage437 => byte_to_char_cp437(b),
        CharacterTable::Codepage1047 => byte_to_char_cp1047(b),
        CharacterTable::Braille => byte_to_char_braille(b),
