#[cfg(unix)]
fn libc_isatty(fd: i32) -> bool {
    extern "C" {
        fn isatty(fd: i32) -> i32;
    }
    unsafe { isatty(fd) != 0 }
}

#[cfg(not(unix))]
fn libc_isatty(_fd: i32) -> bool {
    false
}

fn get_terminal_width() -> u32 {
    // Try to get terminal width
    #[cfg(unix)]
    {
        extern "C" {
            fn ioctl(fd: i32, request: u64, ...) -> i32;
        }
        #[repr(C)]
        struct Winsize {
            ws_row: u16,
            ws_col: u16,
            ws_xpixel: u16,
            ws_ypixel: u16,
        }
        let mut ws = Winsize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
        unsafe {
            if ioctl(1, 0x5413, &mut ws as *mut Winsize) == 0 && ws.ws_col > 0 {
                return ws.ws_col as u32;
            }
        }
    }
    80 // default
}

struct LineConfig {
    panels: usize,
    group_size: usize,
    bytes_per_line: usize,
    offset_width: usize,
    show_position: bool,
    show_chars: bool,
    bpu: usize, // bytes_per_unit
}

fn compute_panels(args: &Args, bpu: usize) -> usize {
    let group_size = args.group_size.clone() as usize;
    let bytes_per_group = group_size;

    if let Some(PanelsArg::Count(n)) = &args.panels {
        return *n;
    }

    if let Some(width) = args.terminal_width {
        // Calculate max panels that fit in width
        return calc_panels_for_width(width, bpu, group_size, args);
    }

    if let Some(PanelsArg::Auto) = &args.panels {
        let width = get_terminal_width();
        return calc_panels_for_width(width, bpu, group_size, args);
    }

    // Default: try 2 panels, fall back to 1 if too narrow
    2
}

fn calc_panels_for_width(width: u32, bpu: usize, group_size: usize, args: &Args) -> usize {
    // Try panels from high to low
    for panels in (1..=16).rev() {
        let line_len = compute_line_width(panels, bpu, group_size, args);
        if line_len <= width as usize {
            return panels;
        }
    }
    1
}

fn compute_line_width(panels: usize, bpu: usize, group_size: usize, args: &Args) -> usize {
    let show_pos = !args.no_position && !args.plain;
    let show_chars = !args.no_characters && !args.plain;
    let bytes_per_group = group_size;
    let groups_per_panel = 8 / group_size.max(1);
    let bytes_per_panel = 8;

    // bytes_per_unit * group_size + space separator between groups, per panel
    // hex panel: "xx xx xx xx xx xx xx xx" = 8*3-1 for group_size=1
    let hex_chars_per_panel = bpu * group_size * groups_per_panel + (groups_per_panel - 1);

    // Border chars
    let border_chars = if args.border == BorderStyle::None { 2 } else { 1 };

    let mut total = 0;
    if show_pos {
        total += 8 + 2; // offset + separators
    }
    total += panels * (hex_chars_per_panel + 2); // hex + separators
    total += panels - 1; // inter-panel separators (the ┊ chars)
    if show_chars {
        total += panels * (bytes_per_panel + 2); // char panels + separators
    }

    total
}

fn offset_width_for(max_offset: u64) -> usize {
    if max_offset <= 0xffffffff { 8 } else {
        let hex = format!("{:x}", max_offset);
        hex.len().max(8)
    }
}

pub fn run(mut args: Args, out: &mut impl Write) -> Result<(), String> {
    let prog_name = std::env::args().next().unwrap_or_else(|| "hexyl".to_string());

    if args.version {
        writeln!(out, "hexyl 0.16.0").map_err(|e| e.to_string())?;
        return Ok(());
    }

    if args.help || args.help_short {
        print_help(out, &prog_name, args.help_short);
        return Ok(());
    }

    if let Some(shell) = &args.completion {
        print_completion(out, shell);
        return Ok(());
    }

    if args.print_color_table {
        print_color_table(out);
        return Ok(());
    }

    // Apply --plain flag
    if args.plain {
        args.no_characters = true;
        args.no_position = true;
        args.border = BorderStyle::None;
        args.color = ColorWhen::Never;
    }

    // -C overrides --no-characters
    if args.characters {
        args.no_characters = false;
    }

    let colorize = uses_color(&args);
    let colors = get_colors();

    // Open input
    let mut reader: Box<dyn Read> = if let Some(path) = &args.file {
        let f = File::open(path).map_err(|e| format!("{}", e))?;

        // Handle skip for files
        if let Some(skip) = args.skip {
            let mut f = f;
            if skip < 0 {
                // Seek from end
                f.seek(SeekFrom::End(skip)).map_err(|e| format!("{}", e))?;
            } else {
                f.seek(SeekFrom::Start(skip as u64)).map_err(|e| format!("{}", e))?;
            }
            Box::new(f)
        } else {
            Box::new(f)
        }
    } else {
        // stdin
        let stdin = io::stdin();
        if let Some(skip) = args.skip {
            if skip < 0 {
                return Err("negative skip not supported for stdin".to_string());
            }
            // Skip bytes from stdin
            let mut stdin = stdin.lock();
            let mut buf = vec![0u8; skip as usize];
            let _ = stdin.read_exact(&mut buf);
            Box::new(io::stdin())
        } else {
            Box::new(io::stdin())
        }
    };

    // Read up to length bytes
    let data: Vec<u8> = if let Some(len) = args.length {
        let mut buf = vec![0u8; len as usize];
        let mut total = 0;
        loop {
            match reader.read(&mut buf[total..]) {
                Ok(0) => break,
                Ok(n) => { total += n; if total >= len as usize { break; } }
                Err(e) => return Err(format!("{}", e)),
            }
        }
        buf[..total].to_vec()
    } else {
        let mut buf = Vec::new();
        reader.read_to_end(&mut buf).map_err(|e| format!("{}", e))?;
        buf
    };

    // Determine display offset
    let display_offset_base: u64 = if args.display_offset >= 0 {
        args.display_offset as u64
    } else {
        // negative: relative to file size (need to know file size)
        // For files only
        if let Some(path) = &args.file {
            let metadata = std::fs::metadata(path).map_err(|e| format!("{}", e))?;
            let file_size = metadata.len();
            let skip_pos = if let Some(skip) = args.skip {
                if skip < 0 { (file_size as i64 + skip).max(0) as u64 }
                else { skip as u64 }
            } else { 0 };
            let abs_offset = (file_size as i64 + args.display_offset).max(0) as u64;
            abs_offset
        } else {
            0
        }
    };

    // C include output
    if args.include {
        write_c_include(out, &data).map_err(|e| e.to_string())?;
        return Ok(());
    }

    // Determine number of panels
    let bpu = bytes_per_unit(&args.base);
    let group_size = args.group_size.clone() as usize;
    let bytes_per_panel = 8;

    let panels = compute_panels(&args, bpu);
    let bytes_per_line = bytes_per_panel * panels;

    // Compute offset column width based on max offset
    let max_offset = display_offset_base + data.len() as u64;
    let off_width = offset_width_for(max_offset);

    let show_pos = !args.no_position && args.border != BorderStyle::None;
    let show_chars = !args.no_characters;

    // Print border top
    print_border_top(out, &args, panels, bpu, group_size, off_width, show_pos, show_chars)?;

    if data.is_empty() {
        // Print "No content" line
        print_no_content(out, &args, panels, bpu, group_size, off_width, show_pos, show_chars)?;
    } else {
        let mut line_offset: u64 = 0;
        let mut prev_line: Option<Vec<u8>> = None;
        let mut squeezing = false;

        while line_offset < data.len() as u64 {
            let line_start = line_offset as usize;
            let line_end = (line_start + bytes_per_line).min(data.len());
            let line_bytes = &data[line_start..line_end];

            // Check squeezing
            if !args.no_squeezing {
                if let Some(ref prev) = prev_line {
                    if line_bytes == prev.as_slice() && line_end == line_start + bytes_per_line {
                        // This is a duplicate full line
                        if !squeezing {
                            // Print the asterisk
                            print_squeeze_line(out, &args, off_width, show_pos, show_chars)?;
                            squeezing = true;
                        }
                        line_offset += bytes_per_line as u64;
                        continue;
                    } else {
                        squeezing = false;
                    }
                }
            }

            squeezing = false;
            prev_line = Some(line_bytes.to_vec());

            let abs_offset = display_offset_base + line_offset;
            print_hex_line(out, &args, line_bytes, abs_offset, panels, bpu, group_size,
                           bytes_per_line, off_width, show_pos, show_chars, colorize, &colors)?;

            line_offset += line_bytes.len() as u64;
        }
    }

    // Print border bottom
    print_border_bottom(out, &args, panels, bpu, group_size, off_width, show_pos, show_chars)?;

    out.flush().map_err(|e| e.to_string())?;
    Ok(())
}

fn panel_hex_width(bpu: usize, group_size: usize) -> usize {
    // Width of one panel's hex section
    let groups = 8 / group_size;
    let chars_per_group = bpu * group_size;
    chars_per_group * groups + (groups - 1) // spaces between groups
}

fn hex_row(bytes: &[u8], panel_idx: usize, bpu: usize, group_size: usize, 
           bytes_per_panel: usize, endianness: &Endianness, base: &Base) -> String {
    let start = panel_idx * bytes_per_panel;
    let end = (start + bytes_per_panel).min(bytes.len());
    let panel_bytes = &bytes[start..end];

    let groups = 8 / group_size;
    let mut parts = Vec::new();

    for g in 0..groups {
        let gs = g * group_size;
        let ge = gs + group_size;
        let group_bytes_slice: Vec<u8> = (gs..ge).map(|k| {
            if k < panel_bytes.len() { panel_bytes[k] } else { 0 }
        }).collect();

        let ordered: Vec<u8> = if *endianness == Endianness::Little {
            group_bytes_slice.iter().rev().cloned().collect()
        } else {
            group_bytes_slice.clone()
        };

        let count_in_panel = (ge.min(panel_bytes.len())).saturating_sub(gs);
        if count_in_panel == 0 {
            // Pad with spaces
            let pad_len = bpu * group_size;
            parts.push(" ".repeat(pad_len));
        } else if count_in_panel < group_size {
            // Partial group
            let mut s = String::new();
            if *endianness == Endianness::Little {
                // Partial little-endian: show valid bytes reversed + padding
                // For little endian with partial group, the bytes that exist come at the end
                let pad = group_size - count_in_panel;
                s.push_str(&" ".repeat(bpu * pad));
                for i in (0..count_in_panel).rev() {
                    s.push_str(&format_byte(group_bytes_slice[i], base));
                }
            } else {
                // Big endian: valid bytes first, then spaces
                for i in 0..count_in_panel {
                    s.push_str(&format_byte(group_bytes_slice[i], base));
                }
                let pad = group_size - count_in_panel;
                s.push_str(&" ".repeat(bpu * pad + if pad > 0 { pad - 1 } else { 0 }));
                // Actually just spaces to fill the group width
                let expected_len = bpu * group_size;
                while s.len() < expected_len {
                    s.push(' ');
                }
                s.truncate(expected_len);
            }
            parts.push(s);
        } else {
            let mut s = String::new();
            for b in &ordered {
                s.push_str(&format_byte(*b, base));
            }
            parts.push(s);
        }
    }

    parts.join(" ")
}

fn print_border_top(out: &mut impl Write, args: &Args, panels: usize, bpu: usize, group_size: usize,
                    off_width: usize, show_pos: bool, show_chars: bool) -> Result<(), String> {
    match args.border {
        BorderStyle::None => return Ok(()),
        BorderStyle::Ascii => {
            let line = build_border_line('+', '-', '+', args, panels, bpu, group_size, off_width, show_pos, show_chars);
            writeln!(out, "{}", line).map_err(|e| e.to_string())?;
        }
        BorderStyle::Unicode => {
            let line = build_border_line('\u{250C}', '\u{2500}', '\u{2510}', args, panels, bpu, group_size, off_width, show_pos, show_chars);
            writeln!(out, "{}", line).map_err(|e| e.to_string())?;
        }
    }
    Ok(())
}

