fn build_border_line(left: char, fill: char, right: char, args: &Args, panels: usize, bpu: usize,
                     group_size: usize, off_width: usize, show_pos: bool, show_chars: bool) -> String {
    let hex_w = panel_hex_width(bpu, group_size);
    let char_w = 8; // char panel width

    let bar = match &args.border {
        BorderStyle::Unicode => '\u{2524}',  // ┤  -- not right, use the correct ones
        BorderStyle::Ascii => '+',
        BorderStyle::None => ' ',
    };

    let (h_sep, v_inner) = match &args.border {
        BorderStyle::Unicode => ('\u{2500}', '\u{252C}'),
        BorderStyle::Ascii => ('-', '+'),
        BorderStyle::None => ('-', '+'),
    };

    let mut s = String::new();
    s.push(left);

    if show_pos {
        s.push_str(&fill.to_string().repeat(off_width));
        s.push(v_inner);
    }

    for p in 0..panels {
        s.push_str(&fill.to_string().repeat(hex_w + 2)); // 1 space on each side
        if p < panels - 1 {
            s.push(v_inner);
        }
    }

    if show_chars {
        s.push(v_inner);
        for p in 0..panels {
            s.push_str(&fill.to_string().repeat(char_w));
            if p < panels - 1 {
                s.push(v_inner);
            }
        }
    }

    s.push(right);
    s
}

fn print_no_content(out: &mut impl Write, args: &Args, panels: usize, bpu: usize, group_size: usize,
                    off_width: usize, show_pos: bool, show_chars: bool) -> Result<(), String> {
    let hex_w = panel_hex_width(bpu, group_size);
    let char_w = 8;

    let (left, right, v_sep) = match &args.border {
        BorderStyle::Unicode => ('\u{2502}', '\u{2502}', '\u{2502}'),
        BorderStyle::Ascii => ('|', '|', '|'),
        BorderStyle::None => (' ', ' ', ' '),
    };

    let mut s = String::new();
    s.push(left);

    if show_pos {
        s.push_str(&" ".repeat(off_width));
        s.push(v_sep);
    }

    // First panel shows "No content"
    let no_content = " No content";
    let pad = hex_w + 2 - no_content.len();
    s.push_str(no_content);
    s.push_str(&" ".repeat(pad));

    for p in 1..panels {
        s.push(v_sep);
        s.push_str(&" ".repeat(hex_w + 2));
    }

    if show_chars {
        s.push(v_sep);
        for p in 0..panels {
            s.push_str(&" ".repeat(char_w));
            if p < panels - 1 {
                s.push(v_sep);
            }
        }
    }

    s.push(right);
    writeln!(out, "{}", s).map_err(|e| e.to_string())?;
    Ok(())
}

fn print_squeeze_line(out: &mut impl Write, args: &Args, off_width: usize, 
                      show_pos: bool, show_chars: bool) -> Result<(), String> {
    match &args.border {
        BorderStyle::None => {
            // For border=none, the squeeze indicator is different
            let (left, right, v_sep) = (' ', ' ', ' ');
            let mut s = String::new();
            if show_pos {
                s.push_str("*");
                s.push_str(&" ".repeat(off_width - 1));
                s.push(' ');
            } else {
                s.push_str("* ");
            }
            writeln!(out, "{}", s.trim_end()).map_err(|e| e.to_string())?;
        }
        BorderStyle::Ascii | BorderStyle::Unicode => {
            let (left, right, v_sep) = match &args.border {
                BorderStyle::Unicode => ('\u{2502}', '\u{2502}', '\u{2502}'),
                _ => ('|', '|', '|'),
            };
            let mut s = String::new();
            s.push(left);
            s.push('*');
            // fill with spaces
            let hex_w = panel_hex_width(bytes_per_unit(&args.base), args.group_size.clone() as usize);
            if show_pos {
                s.push_str(&" ".repeat(off_width - 1));
                s.push(v_sep);
            }
            // rest is empty
            // Actually from the observed output, the squeeze line is:
            // │*       │                         ┊                         │        ┊        │
            // So it's: │ + * + spaces + │ + spaces + ┊ + spaces + │ + spaces + ┊ + spaces + │
            // i.e., like a data line but with * in offset and spaces elsewhere
            writeln!(out, "{}", s).map_err(|e| e.to_string())?;
        }
    }
    Ok(())
}

fn print_hex_line(out: &mut impl Write, args: &Args, bytes: &[u8], offset: u64,
                  panels: usize, bpu: usize, group_size: usize, bytes_per_line: usize,
                  off_width: usize, show_pos: bool, show_chars: bool,
                  colorize: bool, colors: &Colors) -> Result<(), String> {
    let bytes_per_panel = 8;
    let hex_w = panel_hex_width(bpu, group_size);
    let char_w = 8;

    match &args.border {
        BorderStyle::None => {
            let mut s = String::new();
            if show_pos {
                if colorize {
                    s.push_str(&colors.offset.escape_code());
                }
                s.push_str(&format!("{:0width$x}", offset, width = off_width));
                if colorize { s.push_str(RESET); }
                s.push_str("  ");
            }

            for p in 0..panels {
                let panel_start = p * bytes_per_panel;
                let panel_bytes = if panel_start < bytes.len() {
                    &bytes[panel_start..bytes.len().min(panel_start + bytes_per_panel)]
                } else {
                    &[]
                };

                s.push_str(&build_hex_part(panel_bytes, bpu, group_size, &args.endianness, &args.base, colorize, colors, &args.color_scheme));

                let displayed_len = hex_w;
                let actual_len = count_visible_len(&build_hex_part_plain(panel_bytes, bpu, group_size, &args.endianness, &args.base));
                let pad = displayed_len - actual_len;
                s.push_str(&" ".repeat(pad));

                if p < panels - 1 {
                    s.push_str("  ");  // 2 spaces between panels
                }
            }

            if show_chars {
                s.push_str("  ");
                for p in 0..panels {
                    let panel_start = p * bytes_per_panel;
                    let panel_bytes = if panel_start < bytes.len() {
                        &bytes[panel_start..bytes.len().min(panel_start + bytes_per_panel)]
                    } else {
                        &[]
                    };
                    s.push_str(&build_char_part(panel_bytes, &args.character_table, colorize, colors, &args.color_scheme));
                    let char_count: usize = panel_bytes.len();
                    let pad = char_w - char_count;
                    s.push_str(&" ".repeat(pad));
                    if p < panels - 1 {
                        s.push(' ');
                    }
                }
                s.push(' ');
            }

            writeln!(out, "{}", s).map_err(|e| e.to_string())?;
        }
        border_style => {
            let (left, right, v_sep, inner_sep) = match border_style {
                BorderStyle::Unicode => ('\u{2502}', '\u{2502}', '\u{2502}', '\u{250A}'),
                _ => ('|', '|', '|', '|'),
            };
            let inner_div = match border_style {
                BorderStyle::Unicode => '\u{250A}',
                _ => '|',
            };
            // Actually the inter-panel separator in data rows is ┊ (U+250A) for unicode
            let panel_sep = match border_style {
                BorderStyle::Unicode => '\u{250A}', // ┊
                _ => '|',
            };

            let mut s = String::new();
            s.push(left);

            if show_pos {
                if colorize {
                    s.push_str(&colors.offset.escape_code());
                }
                s.push_str(&format!("{:0width$x}", offset, width = off_width));
                if colorize { s.push_str(RESET); }
                s.push(v_sep);
            }

            for p in 0..panels {
                s.push(' ');
                let panel_start = p * bytes_per_panel;
                let panel_bytes = if panel_start < bytes.len() {
                    &bytes[panel_start..bytes.len().min(panel_start + bytes_per_panel)]
                } else {
                    &[]
                };

                s.push_str(&build_hex_part(panel_bytes, bpu, group_size, &args.endianness, &args.base, colorize, colors, &args.color_scheme));

                let actual_len = count_visible_len(&build_hex_part_plain(panel_bytes, bpu, group_size, &args.endianness, &args.base));
                let pad = hex_w - actual_len;
                s.push_str(&" ".repeat(pad));

                s.push(' ');

                if p < panels - 1 {
                    s.push(panel_sep);
                }
            }

            if show_chars {
                s.push(v_sep);
                for p in 0..panels {
                    let panel_start = p * bytes_per_panel;
                    let panel_bytes = if panel_start < bytes.len() {
                        &bytes[panel_start..bytes.len().min(panel_start + bytes_per_panel)]
                    } else {
                        &[]
                    };
                    s.push_str(&build_char_part(panel_bytes, &args.character_table, colorize, colors, &args.color_scheme));
                    let char_count: usize = panel_bytes.len();
                    let pad = char_w - char_count;
                    s.push_str(&" ".repeat(pad));
                    if p < panels - 1 {
                        s.push(panel_sep);
                    }
                }
            }

            s.push(right);
            writeln!(out, "{}", s).map_err(|e| e.to_string())?;
        }
    }
    Ok(())
}

fn count_visible_len(s: &str) -> usize {
    s.len() // plain string, no ANSI codes
}

fn build_hex_part_plain(bytes: &[u8], bpu: usize, group_size: usize, endianness: &Endianness, base: &Base) -> String {
    let groups = 8 / group_size;
    let mut parts = Vec::new();

    for g in 0..groups {
        let gs = g * group_size;
        let ge = gs + group_size;

        if gs >= bytes.len() {
            // Empty group - full spaces
            parts.push(" ".repeat(bpu * group_size));
        } else {
            let count = ge.min(bytes.len()) - gs;
            let group = &bytes[gs..gs + count];

            if count < group_size {
                // Partial group
                let mut s = String::new();
                if *endianness == Endianness::Little {
                    let pad = group_size - count;
                    s.push_str(&" ".repeat(bpu * pad));
                    for b in group.iter().rev() {
                        s.push_str(&format_byte(*b, base));
                    }
                } else {
                    for b in group {
                        s.push_str(&format_byte(*b, base));
                    }
                    let pad = group_size - count;
                    s.push_str(&" ".repeat(bpu * pad));
                }
                parts.push(s);
            } else {
                // Full group
                let ordered: Vec<u8> = if *endianness == Endianness::Little {
                    group.iter().rev().cloned().collect()
                } else {
                    group.to_vec()
                };
                let mut s = String::new();
                for b in &ordered {
                    s.push_str(&format_byte(*b, base));
                }
                parts.push(s);
            }
        }
    }

    parts.join(" ")
}

fn build_hex_part(bytes: &[u8], bpu: usize, group_size: usize, endianness: &Endianness, base: &Base,
                  colorize: bool, colors: &Colors, scheme: &ColorScheme) -> String {
    if !colorize {
        return build_hex_part_plain(bytes, bpu, group_size, endianness, base);
    }

    let groups = 8 / group_size;
    let mut parts = Vec::new();
    let mut last_color: Option<String> = None;

    for g in 0..groups {
        let gs = g * group_size;
        let ge = gs + group_size;

        if gs >= bytes.len() {
            if last_color.is_some() {
                parts.push(RESET.to_string());
                last_color = None;
            }
            parts.push(" ".repeat(bpu * group_size));
        } else {
            let count = ge.min(bytes.len()) - gs;

            // For coloring, we need each byte's color
            // In big endian: bytes go in order
            // In little endian: bytes are reversed but colors should match the original bytes

            let byte_indices: Vec<usize> = (gs..gs+count).collect();
            let ordered_indices: Vec<usize> = if *endianness == Endianness::Little {
                byte_indices.iter().rev().cloned().collect()
            } else {
                byte_indices.clone()
            };

            if count < group_size {
                let mut s = String::new();
                if *endianness == Endianness::Little {
                    let pad = group_size - count;
                    if last_color.is_some() {
                        s.push_str(RESET);
                        last_color = None;
                    }
                    s.push_str(&" ".repeat(bpu * pad));
                    for &bi in &ordered_indices {
                        let b = bytes[bi];
                        let c = byte_color(b, colors, scheme);
                        if last_color.as_deref() != Some(&c) {
                            s.push_str(&c);
                            last_color = Some(c.clone());
                        }
                        s.push_str(&format_byte(b, base));
                    }
                } else {
                    for &bi in &ordered_indices {
                        let b = bytes[bi];
                        let c = byte_color(b, colors, scheme);
                        if last_color.as_deref() != Some(&c) {
                            s.push_str(&c);
                            last_color = Some(c.clone());
                        }
                        s.push_str(&format_byte(b, base));
                    }
                    let pad = group_size - count;
                    if last_color.is_some() {
                        s.push_str(RESET);
                        last_color = None;
                    }
                    s.push_str(&" ".repeat(bpu * pad));
                }
                parts.push(s);
            } else {
                let mut s = String::new();
                // Map from display order to original byte index
                let display_to_orig: Vec<usize> = if *endianness == Endianness::Little {
                    (gs..ge).rev().collect()
                } else {
                    (gs..ge).collect()
                };

                for &bi in &display_to_orig {
                    let b = bytes[bi];
                    let c = byte_color(b, colors, scheme);
                    if last_color.as_deref() != Some(&c) {
                        s.push_str(&c);
                        last_color = Some(c.clone());
                    }
                    s.push_str(&format_byte(b, base));
                }
                parts.push(s);
            }
        }
    }

    if last_color.is_some() {
        parts.push(RESET.to_string());
    }

    parts.join(" ")
}

fn byte_color(b: u8, colors: &Colors, scheme: &ColorScheme) -> String {
    match scheme {
        ColorScheme::Default => byte_color_default(b, colors).escape_code(),
        ColorScheme::Gradient => byte_color_gradient(b).escape_code(),
    }
}

fn build_char_part(bytes: &[u8], table: &CharacterTable, colorize: bool, 
                   colors: &Colors, scheme: &ColorScheme) -> String {
    let mut s = String::new();
    let mut last_color: Option<String> = None;

    for &b in bytes {
        let c = byte_to_char(b, table);

        if colorize {
            let col = byte_color(b, colors, scheme);
            if last_color.as_deref() != Some(&col) {
                s.push_str(&col);
                last_color = Some(col);
            }
        }
        s.push(c);
    }

    if colorize && last_color.is_some() {
        s.push_str(RESET);
    }

    s
}

fn write_c_include(out: &mut impl Write, data: &[u8]) -> io::Result<()> {
    if data.is_empty() {
        return Ok(());
    }

    let mut parts = Vec::new();
    for b in data {
        parts.push(format!("0x{:02x}", b));
    }
    writeln!(out, "  {}", parts.join(", "))?;
    Ok(())
}

fn print_color_table(out: &mut impl Write) {
    let _ = writeln!(out, "hexyl color reference:\n");
    let _ = write!(out, "\x1b[90m\u{22C4} NULL bytes (0x00)\n\x1b[39m");
    let _ = write!(out, "\x1b[36ma ASCII printable characters (0x20 - 0x7E)\n\x1b[39m");
    let _ = write!(out, "\x1b[32m_ ASCII whitespace (0x09 - 0x0D, 0x20)\n\x1b[39m");
    let _ = write!(out, "\x1b[32m\u{2022} ASCII control characters (except NULL and whitespace)\n\x1b[39m");
    let _ = write!(out, "\x1b[33m\u{00D7} Non-ASCII bytes (0x80 - 0xFF)\n\x1b[39m");
}

fn print_help(out: &mut impl Write, prog_name: &str, short: bool) {
    let bin = std::path::Path::new(prog_name)
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or(prog_name);

    if short {
        let _ = write!(out, "{}", SHORT_HELP.replace("hexyl", bin));
    } else {
        let _ = write!(out, "{}", LONG_HELP.replace("hexyl", bin));
    }
}

fn print_completion(out: &mut impl Write, shell: &str) {
    match shell {
