fn is_whitespace(b: u8) -> bool {
    matches!(b, 0x09 | 0x0a | 0x0b | 0x0c | 0x0d | 0x20)
}

fn byte_color_default(b: u8, colors: &Colors) -> &Color {
    if b == 0x00 {
        &colors.null
    } else if b >= 0x80 {
        &colors.nonascii
    } else if b == 0x20 || (b >= 0x21 && b <= 0x7e) {
        &colors.printable
    } else if is_whitespace(b) {
        &colors.whitespace
    } else {
        &colors.other_ascii
    }
}

