        0x20 => ' ',
        0x09..=0x0d => '_',          // whitespace (tab, lf, vt, ff, cr) -> '_'
        0x21..=0x7e => b as char,   // printable
        _ if b >= 0x80 => '\u{00D7}', // × for non-ASCII
        _ => '\u{2022}',             // • for other ASCII
    }
}

fn byte_to_char_ascii(b: u8) -> char {
    match b {
        0x20 => ' ',
        0x21..=0x7e => b as char,
        _ => '.',
    }
}

fn byte_to_char_cp437(b: u8) -> char {
