    printable: Color,
    whitespace: Color,
    other_ascii: Color,
    nonascii: Color,
    offset: Color,
}

fn parse_env_color(name: &str) -> Option<Color> {
    let val = std::env::var(name).ok()?;
    let val = val.trim().to_lowercase();
    match val.as_str() {
        "black" => Some(Color::Ansi(30)),
        "red" => Some(Color::Ansi(31)),
        "green" => Some(Color::Ansi(32)),
        "yellow" => Some(Color::Ansi(33)),
        "blue" => Some(Color::Ansi(34)),
        "magenta" => Some(Color::Ansi(35)),
        "cyan" => Some(Color::Ansi(36)),
        "white" => Some(Color::Ansi(37)),
        "bright black" => Some(Color::Ansi(90)),
        "bright red" => Some(Color::Ansi(91)),
        "bright green" => Some(Color::Ansi(92)),
        "bright yellow" => Some(Color::Ansi(93)),
        "bright blue" => Some(Color::Ansi(94)),
        "bright magenta" => Some(Color::Ansi(95)),
        "bright cyan" => Some(Color::Ansi(96)),
        "bright white" => Some(Color::Ansi(97)),
        _ => {
            // Check hex format #rrggbb
            let orig = std::env::var(name).ok()?;
            let orig = orig.trim();
            if orig.starts_with('#') && orig.len() == 7 {
                let r = u8::from_str_radix(&orig[1..3], 16).ok()?;
                let g = u8::from_str_radix(&orig[3..5], 16).ok()?;
                let b = u8::from_str_radix(&orig[5..7], 16).ok()?;
                Some(Color::Rgb(r, g, b))
            } else {
                None
            }
        }
    }
}

fn get_colors() -> Colors {
    Colors {
        null: parse_env_color("HEXYL_COLOR_NULL").unwrap_or(Color::Ansi(90)),
        printable: parse_env_color("HEXYL_COLOR_ASCII_PRINTABLE").unwrap_or(Color::Ansi(36)),
        whitespace: parse_env_color("HEXYL_COLOR_ASCII_WHITESPACE").unwrap_or(Color::Ansi(32)),
        other_ascii: parse_env_color("HEXYL_COLOR_ASCII_OTHER").unwrap_or(Color::Ansi(32)),
        nonascii: parse_env_color("HEXYL_COLOR_NONASCII").unwrap_or(Color::Ansi(33)),
        offset: parse_env_color("HEXYL_COLOR_OFFSET").unwrap_or(Color::Ansi(90)),
    }
}

fn is_whitespace(b: u8) -> bool {
    matches!(b, 0x09 | 0x0a | 0x0b | 0x0c | 0x0d | 0x20)
}

fn byte_color_default(b: u8, colors: &Colors) -> &Color {
    if b == 0x00 {
        &colors.null
    } else if b >= 0x80 {
        &colors.nonascii
    } else if b == 0x20 || (b >= 0x21 && b <= 0x7e) {
        &colors.printable
    } else if is_whitespace(b) {
        &colors.whitespace
    } else {
        &colors.other_ascii
    }
}

fn byte_color_gradient(b: u8) -> Color {
    let (r, g, bl) = GRADIENT_COLORS[b as usize];
    Color::Rgb(r, g, bl)
}

fn byte_to_char_default(b: u8) -> char {
    match b {
        0x00 => '\u{22C4}',          // ⋄
        0x20 => ' ',
        0x09..=0x0d => '_',          // whitespace (tab, lf, vt, ff, cr) -> '_'
        0x21..=0x7e => b as char,   // printable
        _ if b >= 0x80 => '\u{00D7}', // × for non-ASCII
        _ => '\u{2022}',             // • for other ASCII
    }
}

fn byte_to_char_ascii(b: u8) -> char {
    match b {
        0x20 => ' ',
        0x21..=0x7e => b as char,
        _ => '.',
    }
}

fn byte_to_char_cp437(b: u8) -> char {
    CP437[b as usize]
}

fn byte_to_char_cp1047(b: u8) -> char {
    match CP1047[b as usize] {
        Some(c) => c,
        None => '.',
    }
}

fn byte_to_char_braille(b: u8) -> char {
    BRAILLE[b as usize]
}

fn byte_to_char(b: u8, table: &CharacterTable) -> char {
    match table {
        CharacterTable::Default => byte_to_char_default(b),
        CharacterTable::Ascii => byte_to_char_ascii(b),
        CharacterTable::Codepage437 => byte_to_char_cp437(b),
        CharacterTable::Codepage1047 => byte_to_char_cp1047(b),
        CharacterTable::Braille => byte_to_char_braille(b),
    }
}

fn format_byte(b: u8, base: &Base) -> String {
    match base {
        Base::Hexadecimal => format!("{:02x}", b),
        Base::Decimal => format!("{:03}", b),
        Base::Octal => format!("{:03o}", b),
        Base::Binary => format!("{:08b}", b),
    }
}

fn bytes_per_unit(base: &Base) -> usize {
    match base {
        Base::Hexadecimal => 2,
        Base::Decimal => 3,
        Base::Octal => 3,
        Base::Binary => 8,
    }
}

fn uses_color(args: &Args) -> bool {
    match &args.color {
        ColorWhen::Always => true,
        ColorWhen::Force => true,
        ColorWhen::Never => false,
        ColorWhen::Auto => {
            // Check NO_COLOR
            if std::env::var("NO_COLOR").is_ok() {
                return false;
            }
            // Check if stdout is a tty
            unsafe { libc_isatty(1) }
        }
    }
}

#[cfg(unix)]
fn libc_isatty(fd: i32) -> bool {
    extern "C" {
        fn isatty(fd: i32) -> i32;
    }
    unsafe { isatty(fd) != 0 }
}

#[cfg(not(unix))]
fn libc_isatty(_fd: i32) -> bool {
    false
}

fn get_terminal_width() -> u32 {
    // Try to get terminal width
    #[cfg(unix)]
    {
        extern "C" {
            fn ioctl(fd: i32, request: u64, ...) -> i32;
        }
        #[repr(C)]
        struct Winsize {
            ws_row: u16,
            ws_col: u16,
            ws_xpixel: u16,
            ws_ypixel: u16,
        }
        let mut ws = Winsize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
        unsafe {
            if ioctl(1, 0x5413, &mut ws as *mut Winsize) == 0 && ws.ws_col > 0 {
                return ws.ws_col as u32;
            }
        }
    }
    80 // default
}

struct LineConfig {
    panels: usize,
    group_size: usize,
    bytes_per_line: usize,
    offset_width: usize,
    show_position: bool,
    show_chars: bool,
    bpu: usize, // bytes_per_unit
}

fn compute_panels(args: &Args, bpu: usize) -> usize {
    let group_size = args.group_size.clone() as usize;
    let bytes_per_group = group_size;

    if let Some(PanelsArg::Count(n)) = &args.panels {
        return *n;
    }

    if let Some(width) = args.terminal_width {
        // Calculate max panels that fit in width
        return calc_panels_for_width(width, bpu, group_size, args);
    }

    if let Some(PanelsArg::Auto) = &args.panels {
        let width = get_terminal_width();
        return calc_panels_for_width(width, bpu, group_size, args);
    }

    // Default: try 2 panels, fall back to 1 if too narrow
    2
}

fn calc_panels_for_width(width: u32, bpu: usize, group_size: usize, args: &Args) -> usize {
    // Try panels from high to low
    for panels in (1..=16).rev() {
        let line_len = compute_line_width(panels, bpu, group_size, args);
        if line_len <= width as usize {
            return panels;
        }
    }
    1
}

fn compute_line_width(panels: usize, bpu: usize, group_size: usize, args: &Args) -> usize {
    let show_pos = !args.no_position && !args.plain;
    let show_chars = !args.no_characters && !args.plain;
    let bytes_per_group = group_size;
    let groups_per_panel = 8 / group_size.max(1);
    let bytes_per_panel = 8;

    // bytes_per_unit * group_size + space separator between groups, per panel
    // hex panel: "xx xx xx xx xx xx xx xx" = 8*3-1 for group_size=1
    let hex_chars_per_panel = bpu * group_size * groups_per_panel + (groups_per_panel - 1);

    // Border chars
    let border_chars = if args.border == BorderStyle::None { 2 } else { 1 };

    let mut total = 0;
    if show_pos {
        total += 8 + 2; // offset + separators
    }
    total += panels * (hex_chars_per_panel + 2); // hex + separators
    total += panels - 1; // inter-panel separators (the ┊ chars)
    if show_chars {
        total += panels * (bytes_per_panel + 2); // char panels + separators
    }

    total
}

fn offset_width_for(max_offset: u64) -> usize {
    if max_offset <= 0xffffffff { 8 } else {
        let hex = format!("{:x}", max_offset);
        hex.len().max(8)
    }
}

pub fn run(mut args: Args, out: &mut impl Write) -> Result<(), String> {
    let prog_name = std::env::args().next().unwrap_or_else(|| "hexyl".to_string());

    if args.version {
        writeln!(out, "hexyl 0.16.0").map_err(|e| e.to_string())?;
        return Ok(());
    }

    if args.help || args.help_short {
        print_help(out, &prog_name, args.help_short);
        return Ok(());
    }

    if let Some(shell) = &args.completion {
        print_completion(out, shell);
        return Ok(());
    }

    if args.print_color_table {
        print_color_table(out);
        return Ok(());
    }

    // Apply --plain flag
    if args.plain {
        args.no_characters = true;
        args.no_position = true;
        args.border = BorderStyle::None;
        args.color = ColorWhen::Never;
    }

    // -C overrides --no-characters
    if args.characters {
        args.no_characters = false;
    }

    let colorize = uses_color(&args);
    let colors = get_colors();

    // Open input
    let mut reader: Box<dyn Read> = if let Some(path) = &args.file {
        let f = File::open(path).map_err(|e| format!("{}", e))?;

        // Handle skip for files
        if let Some(skip) = args.skip {
            let mut f = f;
            if skip < 0 {
                // Seek from end
                f.seek(SeekFrom::End(skip)).map_err(|e| format!("{}", e))?;
            } else {
                f.seek(SeekFrom::Start(skip as u64)).map_err(|e| format!("{}", e))?;
            }
            Box::new(f)
        } else {
            Box::new(f)
        }
    } else {
        // stdin
        let stdin = io::stdin();
        if let Some(skip) = args.skip {
            if skip < 0 {
                return Err("negative skip not supported for stdin".to_string());
            }
            // Skip bytes from stdin
            let mut stdin = stdin.lock();
            let mut buf = vec![0u8; skip as usize];
            let _ = stdin.read_exact(&mut buf);
            Box::new(io::stdin())
        } else {
            Box::new(io::stdin())
        }
    };

    // Read up to length bytes
    let data: Vec<u8> = if let Some(len) = args.length {
        let mut buf = vec![0u8; len as usize];
        let mut total = 0;
        loop {
            match reader.read(&mut buf[total..]) {
                Ok(0) => break,
                Ok(n) => { total += n; if total >= len as usize { break; } }
                Err(e) => return Err(format!("{}", e)),
            }
        }
        buf[..total].to_vec()
    } else {
        let mut buf = Vec::new();
        reader.read_to_end(&mut buf).map_err(|e| format!("{}", e))?;
        buf
    };

    // Determine display offset
    let display_offset_base: u64 = if args.display_offset >= 0 {
        args.display_offset as u64
    } else {
        // negative: relative to file size (need to know file size)
        // For files only
        if let Some(path) = &args.file {
            let metadata = std::fs::metadata(path).map_err(|e| format!("{}", e))?;
            let file_size = metadata.len();
            let skip_pos = if let Some(skip) = args.skip {
                if skip < 0 { (file_size as i64 + skip).max(0) as u64 }
                else { skip as u64 }
            } else { 0 };
            let abs_offset = (file_size as i64 + args.display_offset).max(0) as u64;
            abs_offset
        } else {
            0
        }
    };

    // C include output
    if args.include {
        write_c_include(out, &data).map_err(|e| e.to_string())?;
        return Ok(());
    }

    // Determine number of panels
    let bpu = bytes_per_unit(&args.base);
    let group_size = args.group_size.clone() as usize;
    let bytes_per_panel = 8;

    let panels = compute_panels(&args, bpu);
    let bytes_per_line = bytes_per_panel * panels;

    // Compute offset column width based on max offset
    let max_offset = display_offset_base + data.len() as u64;
    let off_width = offset_width_for(max_offset);

    let show_pos = !args.no_position && args.border != BorderStyle::None;
    let show_chars = !args.no_characters;

    // Print border top
    print_border_top(out, &args, panels, bpu, group_size, off_width, show_pos, show_chars)?;

    if data.is_empty() {
        // Print "No content" line
        print_no_content(out, &args, panels, bpu, group_size, off_width, show_pos, show_chars)?;
    } else {
        let mut line_offset: u64 = 0;
        let mut prev_line: Option<Vec<u8>> = None;
        let mut squeezing = false;

        while line_offset < data.len() as u64 {
            let line_start = line_offset as usize;
            let line_end = (line_start + bytes_per_line).min(data.len());
            let line_bytes = &data[line_start..line_end];

            // Check squeezing
            if !args.no_squeezing {
                if let Some(ref prev) = prev_line {
                    if line_bytes == prev.as_slice() && line_end == line_start + bytes_per_line {
                        // This is a duplicate full line
                        if !squeezing {
                            // Print the asterisk
                            print_squeeze_line(out, &args, off_width, show_pos, show_chars)?;
                            squeezing = true;
                        }
                        line_offset += bytes_per_line as u64;
                        continue;
                    } else {
                        squeezing = false;
                    }
                }
            }

            squeezing = false;
            prev_line = Some(line_bytes.to_vec());

            let abs_offset = display_offset_base + line_offset;
            print_hex_line(out, &args, line_bytes, abs_offset, panels, bpu, group_size,
                           bytes_per_line, off_width, show_pos, show_chars, colorize, &colors)?;

            line_offset += line_bytes.len() as u64;
        }
    }

    // Print border bottom
    print_border_bottom(out, &args, panels, bpu, group_size, off_width, show_pos, show_chars)?;

    out.flush().map_err(|e| e.to_string())?;
    Ok(())
}

fn panel_hex_width(bpu: usize, group_size: usize) -> usize {
    // Width of one panel's hex section
    let groups = 8 / group_size;
    let chars_per_group = bpu * group_size;
    chars_per_group * groups + (groups - 1) // spaces between groups
}

fn hex_row(bytes: &[u8], panel_idx: usize, bpu: usize, group_size: usize, 
           bytes_per_panel: usize, endianness: &Endianness, base: &Base) -> String {
    let start = panel_idx * bytes_per_panel;
    let end = (start + bytes_per_panel).min(bytes.len());
    let panel_bytes = &bytes[start..end];

    let groups = 8 / group_size;
    let mut parts = Vec::new();

    for g in 0..groups {
        let gs = g * group_size;
        let ge = gs + group_size;
        let group_bytes_slice: Vec<u8> = (gs..ge).map(|k| {
            if k < panel_bytes.len() { panel_bytes[k] } else { 0 }
        }).collect();

        let ordered: Vec<u8> = if *endianness == Endianness::Little {
            group_bytes_slice.iter().rev().cloned().collect()
        } else {
            group_bytes_slice.clone()
        };

        let count_in_panel = (ge.min(panel_bytes.len())).saturating_sub(gs);
        if count_in_panel == 0 {
            // Pad with spaces
            let pad_len = bpu * group_size;
            parts.push(" ".repeat(pad_len));
        } else if count_in_panel < group_size {
            // Partial group
            let mut s = String::new();
            if *endianness == Endianness::Little {
                // Partial little-endian: show valid bytes reversed + padding
                // For little endian with partial group, the bytes that exist come at the end
                let pad = group_size - count_in_panel;
                s.push_str(&" ".repeat(bpu * pad));
                for i in (0..count_in_panel).rev() {
                    s.push_str(&format_byte(group_bytes_slice[i], base));
                }
            } else {
                // Big endian: valid bytes first, then spaces
                for i in 0..count_in_panel {
                    s.push_str(&format_byte(group_bytes_slice[i], base));
                }
                let pad = group_size - count_in_panel;
                s.push_str(&" ".repeat(bpu * pad + if pad > 0 { pad - 1 } else { 0 }));
                // Actually just spaces to fill the group width
                let expected_len = bpu * group_size;
                while s.len() < expected_len {
                    s.push(' ');
                }
                s.truncate(expected_len);
            }
            parts.push(s);
        } else {
            let mut s = String::new();
            for b in &ordered {
                s.push_str(&format_byte(*b, base));
            }
            parts.push(s);
        }
    }

    parts.join(" ")
}

fn print_border_top(out: &mut impl Write, args: &Args, panels: usize, bpu: usize, group_size: usize,
                    off_width: usize, show_pos: bool, show_chars: bool) -> Result<(), String> {
    match args.border {
        BorderStyle::None => return Ok(()),
        BorderStyle::Ascii => {
            let line = build_border_line('+', '-', '+', args, panels, bpu, group_size, off_width, show_pos, show_chars);
            writeln!(out, "{}", line).map_err(|e| e.to_string())?;
        }
        BorderStyle::Unicode => {
            let line = build_border_line('\u{250C}', '\u{2500}', '\u{2510}', args, panels, bpu, group_size, off_width, show_pos, show_chars);
            writeln!(out, "{}", line).map_err(|e| e.to_string())?;
        }
    }
    Ok(())
}

fn print_border_bottom(out: &mut impl Write, args: &Args, panels: usize, bpu: usize, group_size: usize,
                       off_width: usize, show_pos: bool, show_chars: bool) -> Result<(), String> {
    match args.border {
        BorderStyle::None => return Ok(()),
        BorderStyle::Ascii => {
            let line = build_border_line('+', '-', '+', args, panels, bpu, group_size, off_width, show_pos, show_chars);
            writeln!(out, "{}", line).map_err(|e| e.to_string())?;
        }
        BorderStyle::Unicode => {
            let line = build_border_line('\u{2514}', '\u{2500}', '\u{2518}', args, panels, bpu, group_size, off_width, show_pos, show_chars);
            writeln!(out, "{}", line).map_err(|e| e.to_string())?;
        }
    }
    Ok(())
}

fn sep_char(border: &BorderStyle) -> char {
    match border {
        BorderStyle::Unicode => '\u{252C}',
        BorderStyle::Ascii => '+',
        BorderStyle::None => ' ',
    }
}

fn inner_sep_top(border: &BorderStyle) -> char {
    match border {
        BorderStyle::Unicode => '\u{252C}',
        BorderStyle::Ascii => '+',
        BorderStyle::None => ' ',
    }
}

fn build_border_line(left: char, fill: char, right: char, args: &Args, panels: usize, bpu: usize,
                     group_size: usize, off_width: usize, show_pos: bool, show_chars: bool) -> String {
    let hex_w = panel_hex_width(bpu, group_size);
    let char_w = 8; // char panel width

    let bar = match &args.border {
        BorderStyle::Unicode => '\u{2524}',  // ┤  -- not right, use the correct ones
        BorderStyle::Ascii => '+',
        BorderStyle::None => ' ',
    };

    let (h_sep, v_inner) = match &args.border {
        BorderStyle::Unicode => ('\u{2500}', '\u{252C}'),
        BorderStyle::Ascii => ('-', '+'),
        BorderStyle::None => ('-', '+'),
    };

    let mut s = String::new();
    s.push(left);

    if show_pos {
        s.push_str(&fill.to_string().repeat(off_width));
        s.push(v_inner);
    }

    for p in 0..panels {
        s.push_str(&fill.to_string().repeat(hex_w + 2)); // 1 space on each side
        if p < panels - 1 {
            s.push(v_inner);
        }
    }

    if show_chars {
        s.push(v_inner);
        for p in 0..panels {
            s.push_str(&fill.to_string().repeat(char_w));
            if p < panels - 1 {
                s.push(v_inner);
            }
        }
    }

    s.push(right);
    s
}

fn print_no_content(out: &mut impl Write, args: &Args, panels: usize, bpu: usize, group_size: usize,
                    off_width: usize, show_pos: bool, show_chars: bool) -> Result<(), String> {
    let hex_w = panel_hex_width(bpu, group_size);
    let char_w = 8;

    let (left, right, v_sep) = match &args.border {
        BorderStyle::Unicode => ('\u{2502}', '\u{2502}', '\u{2502}'),
        BorderStyle::Ascii => ('|', '|', '|'),
        BorderStyle::None => (' ', ' ', ' '),
    };

    let mut s = String::new();
    s.push(left);

    if show_pos {
        s.push_str(&" ".repeat(off_width));
        s.push(v_sep);
    }

    // First panel shows "No content"
    let no_content = " No content";
    let pad = hex_w + 2 - no_content.len();
    s.push_str(no_content);
    s.push_str(&" ".repeat(pad));

    for p in 1..panels {
        s.push(v_sep);
        s.push_str(&" ".repeat(hex_w + 2));
    }

    if show_chars {
        s.push(v_sep);
        for p in 0..panels {
            s.push_str(&" ".repeat(char_w));
            if p < panels - 1 {
                s.push(v_sep);
            }
        }
    }

    s.push(right);
    writeln!(out, "{}", s).map_err(|e| e.to_string())?;
    Ok(())
}

fn print_squeeze_line(out: &mut impl Write, args: &Args, off_width: usize, 
                      show_pos: bool, show_chars: bool) -> Result<(), String> {
    match &args.border {
        BorderStyle::None => {
            // For border=none, the squeeze indicator is different
            let (left, right, v_sep) = (' ', ' ', ' ');
            let mut s = String::new();
            if show_pos {
                s.push_str("*");
                s.push_str(&" ".repeat(off_width - 1));
                s.push(' ');
            } else {
                s.push_str("* ");
            }
            writeln!(out, "{}", s.trim_end()).map_err(|e| e.to_string())?;
        }
        BorderStyle::Ascii | BorderStyle::Unicode => {
            let (left, right, v_sep) = match &args.border {
                BorderStyle::Unicode => ('\u{2502}', '\u{2502}', '\u{2502}'),
                _ => ('|', '|', '|'),
            };
            let mut s = String::new();
            s.push(left);
            s.push('*');
            // fill with spaces
            let hex_w = panel_hex_width(bytes_per_unit(&args.base), args.group_size.clone() as usize);
            if show_pos {
                s.push_str(&" ".repeat(off_width - 1));
                s.push(v_sep);
            }
            // rest is empty
            // Actually from the observed output, the squeeze line is:
            // │*       │                         ┊                         │        ┊        │
            // So it's: │ + * + spaces + │ + spaces + ┊ + spaces + │ + spaces + ┊ + spaces + │
            // i.e., like a data line but with * in offset and spaces elsewhere
            writeln!(out, "{}", s).map_err(|e| e.to_string())?;
        }
    }
    Ok(())
}

fn print_hex_line(out: &mut impl Write, args: &Args, bytes: &[u8], offset: u64,
                  panels: usize, bpu: usize, group_size: usize, bytes_per_line: usize,
                  off_width: usize, show_pos: bool, show_chars: bool,
                  colorize: bool, colors: &Colors) -> Result<(), String> {
    let bytes_per_panel = 8;
    let hex_w = panel_hex_width(bpu, group_size);
    let char_w = 8;

    match &args.border {
        BorderStyle::None => {
            let mut s = String::new();
            if show_pos {
                if colorize {
                    s.push_str(&colors.offset.escape_code());
                }
                s.push_str(&format!("{:0width$x}", offset, width = off_width));
                if colorize { s.push_str(RESET); }
                s.push_str("  ");
            }

            for p in 0..panels {
                let panel_start = p * bytes_per_panel;
                let panel_bytes = if panel_start < bytes.len() {
                    &bytes[panel_start..bytes.len().min(panel_start + bytes_per_panel)]
                } else {
                    &[]
                };

                s.push_str(&build_hex_part(panel_bytes, bpu, group_size, &args.endianness, &args.base, colorize, colors, &args.color_scheme));

                let displayed_len = hex_w;
                let actual_len = count_visible_len(&build_hex_part_plain(panel_bytes, bpu, group_size, &args.endianness, &args.base));
                let pad = displayed_len - actual_len;
                s.push_str(&" ".repeat(pad));

                if p < panels - 1 {
                    s.push_str("  ");  // 2 spaces between panels
                }
            }

            if show_chars {
                s.push_str("  ");
                for p in 0..panels {
                    let panel_start = p * bytes_per_panel;
                    let panel_bytes = if panel_start < bytes.len() {
                        &bytes[panel_start..bytes.len().min(panel_start + bytes_per_panel)]
                    } else {
                        &[]
                    };
                    s.push_str(&build_char_part(panel_bytes, &args.character_table, colorize, colors, &args.color_scheme));
                    let char_count: usize = panel_bytes.len();
                    let pad = char_w - char_count;
                    s.push_str(&" ".repeat(pad));
                    if p < panels - 1 {
                        s.push(' ');
                    }
                }
                s.push(' ');
            }

            writeln!(out, "{}", s).map_err(|e| e.to_string())?;
        }
        border_style => {
            let (left, right, v_sep, inner_sep) = match border_style {
                BorderStyle::Unicode => ('\u{2502}', '\u{2502}', '\u{2502}', '\u{250A}'),
                _ => ('|', '|', '|', '|'),
            };
            let inner_div = match border_style {
                BorderStyle::Unicode => '\u{250A}',
                _ => '|',
            };
            // Actually the inter-panel separator in data rows is ┊ (U+250A) for unicode
            let panel_sep = match border_style {
                BorderStyle::Unicode => '\u{250A}', // ┊
                _ => '|',
            };

            let mut s = String::new();
            s.push(left);

            if show_pos {
                if colorize {
                    s.push_str(&colors.offset.escape_code());
                }
                s.push_str(&format!("{:0width$x}", offset, width = off_width));
                if colorize { s.push_str(RESET); }
                s.push(v_sep);
            }

            for p in 0..panels {
                s.push(' ');
                let panel_start = p * bytes_per_panel;
                let panel_bytes = if panel_start < bytes.len() {
                    &bytes[panel_start..bytes.len().min(panel_start + bytes_per_panel)]
                } else {
                    &[]
                };

                s.push_str(&build_hex_part(panel_bytes, bpu, group_size, &args.endianness, &args.base, colorize, colors, &args.color_scheme));

                let actual_len = count_visible_len(&build_hex_part_plain(panel_bytes, bpu, group_size, &args.endianness, &args.base));
                let pad = hex_w - actual_len;
                s.push_str(&" ".repeat(pad));

                s.push(' ');

                if p < panels - 1 {
                    s.push(panel_sep);
                }
            }

            if show_chars {
                s.push(v_sep);
                for p in 0..panels {
                    let panel_start = p * bytes_per_panel;
                    let panel_bytes = if panel_start < bytes.len() {
                        &bytes[panel_start..bytes.len().min(panel_start + bytes_per_panel)]
                    } else {
                        &[]
                    };
                    s.push_str(&build_char_part(panel_bytes, &args.character_table, colorize, colors, &args.color_scheme));
                    let char_count: usize = panel_bytes.len();
                    let pad = char_w - char_count;
                    s.push_str(&" ".repeat(pad));
                    if p < panels - 1 {
                        s.push(panel_sep);
                    }
                }
            }

            s.push(right);
            writeln!(out, "{}", s).map_err(|e| e.to_string())?;
        }
    }
    Ok(())
}

fn count_visible_len(s: &str) -> usize {
    s.len() // plain string, no ANSI codes
}

fn build_hex_part_plain(bytes: &[u8], bpu: usize, group_size: usize, endianness: &Endianness, base: &Base) -> String {
    let groups = 8 / group_size;
    let mut parts = Vec::new();

    for g in 0..groups {
        let gs = g * group_size;
        let ge = gs + group_size;

        if gs >= bytes.len() {
            // Empty group - full spaces
            parts.push(" ".repeat(bpu * group_size));
        } else {
            let count = ge.min(bytes.len()) - gs;
            let group = &bytes[gs..gs + count];

            if count < group_size {
                // Partial group
                let mut s = String::new();
                if *endianness == Endianness::Little {
                    let pad = group_size - count;
                    s.push_str(&" ".repeat(bpu * pad));
                    for b in group.iter().rev() {
                        s.push_str(&format_byte(*b, base));
                    }
                } else {
                    for b in group {
                        s.push_str(&format_byte(*b, base));
                    }
                    let pad = group_size - count;
                    s.push_str(&" ".repeat(bpu * pad));
                }
                parts.push(s);
            } else {
                // Full group
                let ordered: Vec<u8> = if *endianness == Endianness::Little {
                    group.iter().rev().cloned().collect()
                } else {
                    group.to_vec()
                };
                let mut s = String::new();
                for b in &ordered {
                    s.push_str(&format_byte(*b, base));
                }
                parts.push(s);
            }
        }
    }

    parts.join(" ")
}

fn build_hex_part(bytes: &[u8], bpu: usize, group_size: usize, endianness: &Endianness, base: &Base,
                  colorize: bool, colors: &Colors, scheme: &ColorScheme) -> String {
    if !colorize {
        return build_hex_part_plain(bytes, bpu, group_size, endianness, base);
    }

    let groups = 8 / group_size;
    let mut parts = Vec::new();
    let mut last_color: Option<String> = None;

    for g in 0..groups {
        let gs = g * group_size;
        let ge = gs + group_size;

        if gs >= bytes.len() {
            if last_color.is_some() {
                parts.push(RESET.to_string());
                last_color = None;
            }
            parts.push(" ".repeat(bpu * group_size));
        } else {
            let count = ge.min(bytes.len()) - gs;

            // For coloring, we need each byte's color
            // In big endian: bytes go in order
            // In little endian: bytes are reversed but colors should match the original bytes

            let byte_indices: Vec<usize> = (gs..gs+count).collect();
            let ordered_indices: Vec<usize> = if *endianness == Endianness::Little {
                byte_indices.iter().rev().cloned().collect()
            } else {
                byte_indices.clone()
            };

            if count < group_size {
                let mut s = String::new();
                if *endianness == Endianness::Little {
                    let pad = group_size - count;
                    if last_color.is_some() {
                        s.push_str(RESET);
                        last_color = None;
                    }
                    s.push_str(&" ".repeat(bpu * pad));
                    for &bi in &ordered_indices {
                        let b = bytes[bi];
                        let c = byte_color(b, colors, scheme);
                        if last_color.as_deref() != Some(&c) {
                            s.push_str(&c);
                            last_color = Some(c.clone());
                        }
                        s.push_str(&format_byte(b, base));
                    }
                } else {
                    for &bi in &ordered_indices {
                        let b = bytes[bi];
                        let c = byte_color(b, colors, scheme);
                        if last_color.as_deref() != Some(&c) {
                            s.push_str(&c);
                            last_color = Some(c.clone());
                        }
                        s.push_str(&format_byte(b, base));
                    }
                    let pad = group_size - count;
                    if last_color.is_some() {
                        s.push_str(RESET);
                        last_color = None;
                    }
                    s.push_str(&" ".repeat(bpu * pad));
                }
                parts.push(s);
            } else {
                let mut s = String::new();
                // Map from display order to original byte index
                let display_to_orig: Vec<usize> = if *endianness == Endianness::Little {
                    (gs..ge).rev().collect()
                } else {
                    (gs..ge).collect()
                };

                for &bi in &display_to_orig {
                    let b = bytes[bi];
                    let c = byte_color(b, colors, scheme);
                    if last_color.as_deref() != Some(&c) {
                        s.push_str(&c);
                        last_color = Some(c.clone());
                    }
                    s.push_str(&format_byte(b, base));
                }
                parts.push(s);
            }
        }
    }

    if last_color.is_some() {
        parts.push(RESET.to_string());
    }

    parts.join(" ")
}

fn byte_color(b: u8, colors: &Colors, scheme: &ColorScheme) -> String {
    match scheme {
        ColorScheme::Default => byte_color_default(b, colors).escape_code(),
        ColorScheme::Gradient => byte_color_gradient(b).escape_code(),
    }
}

fn build_char_part(bytes: &[u8], table: &CharacterTable, colorize: bool, 
                   colors: &Colors, scheme: &ColorScheme) -> String {
    let mut s = String::new();
    let mut last_color: Option<String> = None;

    for &b in bytes {
        let c = byte_to_char(b, table);

        if colorize {
            let col = byte_color(b, colors, scheme);
            if last_color.as_deref() != Some(&col) {
                s.push_str(&col);
                last_color = Some(col);
            }
        }
        s.push(c);
    }

    if colorize && last_color.is_some() {
        s.push_str(RESET);
    }

    s
}

fn write_c_include(out: &mut impl Write, data: &[u8]) -> io::Result<()> {
    if data.is_empty() {
        return Ok(());
    }

    let mut parts = Vec::new();
    for b in data {
        parts.push(format!("0x{:02x}", b));
    }
    writeln!(out, "  {}", parts.join(", "))?;
    Ok(())
}

fn print_color_table(out: &mut impl Write) {
    let _ = writeln!(out, "hexyl color reference:\n");
    let _ = write!(out, "\x1b[90m\u{22C4} NULL bytes (0x00)\n\x1b[39m");
    let _ = write!(out, "\x1b[36ma ASCII printable characters (0x20 - 0x7E)\n\x1b[39m");
    let _ = write!(out, "\x1b[32m_ ASCII whitespace (0x09 - 0x0D, 0x20)\n\x1b[39m");
    let _ = write!(out, "\x1b[32m\u{2022} ASCII control characters (except NULL and whitespace)\n\x1b[39m");
    let _ = write!(out, "\x1b[33m\u{00D7} Non-ASCII bytes (0x80 - 0xFF)\n\x1b[39m");
}

fn print_help(out: &mut impl Write, prog_name: &str, short: bool) {
    let bin = std::path::Path::new(prog_name)
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or(prog_name);

    if short {
        let _ = write!(out, "{}", SHORT_HELP.replace("hexyl", bin));
    } else {
        let _ = write!(out, "{}", LONG_HELP.replace("hexyl", bin));
    }
}

fn print_completion(out: &mut impl Write, shell: &str) {
    match shell {
        "bash" => { let _ = write!(out, "{}", BASH_COMPLETION); }
        "elvish" => { let _ = write!(out, "{}", ELVISH_COMPLETION); }
        "fish" => { let _ = write!(out, "{}", FISH_COMPLETION); }
        "powershell" => { let _ = write!(out, "{}", POWERSHELL_COMPLETION); }
        "zsh" => { let _ = write!(out, "{}", ZSH_COMPLETION); }
        _ => {}
    }
}

