                let hex_plain = build_hex_part_plain(panel_bytes, bpu, group_size, &args.endianness, &args.base);
                s.push_str(&hex_str);
                let pad = hex_w - count_visible_len(&hex_plain);
                s.push_str(&" ".repeat(pad));

